// Renders one outbound message from a named template.
// The email templates are embedded verbatim from automation/emails/*.md —
// that directory is the source of truth. Edit there and re-embed here in
// the same PR (each entry is the whole file: 'Subject: …', blank line, body).
const EMAILS = {
  'step2-invite': `Subject: Next step for {{ collective_name }} — your application to {{ org_name }}

Hi,

Thanks for applying to {{ org_name }} with {{ collective_name }}.

One step left: please fill in our application form, which asks the things we need in
order to review your project properly.

{{ form_url }}

It takes about ten minutes. If anything in it is unclear, reply to this email and a
human will get back to you.

— {{ org_name }}`,
  'reminder': `Subject: Reminder: your application to {{ org_name }} for {{ collective_name }}

Hi,

We sent you a link to the {{ org_name }} application form and haven't had it back yet.

{{ form_url }}

If you're still interested, fill it in when you get a chance. If your plans changed and
you'd rather not go ahead, no need to reply — we'll leave it there.

— {{ org_name }}`,
  'advised-wrong-host': `Subject: Your application to {{ org_name }} for {{ collective_name }} — next step

Hi,

Thanks for applying to {{ org_name }} with {{ collective_name }}.

Before a person reviews your application, an automated check reads what is
currently on your Open Collective page. Its first impression, based only on
that:

{{ ai_applicant_message }}

That is a machine's reading of a short description — not a decision, and it may
simply be wrong. A person will review your application either way.

The next step is the same for everyone: our application form.

{{ form_url }}

If the note above missed the point of your project, the form is exactly where
to set the record straight — the more detail you give, the better the human
review. And if the other host really is the better fit, applying there instead
is completely fine.

Questions or disagreement — reply to this email and a reviewer will read it.

— {{ org_name }}`,
  'advised-not-open-source': `Subject: Your application to {{ org_name }} for {{ collective_name }} — next step

Hi,

Thanks for applying to {{ org_name }} with {{ collective_name }}.

Before a person reviews your application, an automated check reads what is
currently on your Open Collective page. Its first impression, based only on
that:

{{ ai_applicant_message }}

That is a machine's reading of what may be a very short description — not a
decision, and it may simply be wrong. A person will review your application
either way.

The next step is the same for everyone: our application form.

{{ form_url }}

If your project is open source and the note above could not tell, the form is
exactly where to show it — a repository link, the licence, how development
happens in the open. The more detail you give, the better the human review.

Questions or disagreement — reply to this email and a reviewer will read it.

— {{ org_name }}`,
  'form-received': `Subject: We've got your form for {{ collective_name }}

Hi,

Your application form for {{ collective_name }} has arrived. A human will now go through
it — that usually takes a couple of weeks.

No action needed from you for now. We'll email you as soon as there's a decision. If you
need to add or change anything in the meantime, reply to this email.

— {{ org_name }}`,
  'decision-approved': `Subject: {{ collective_name }} is approved on Open Collective

Hi,

Good news: {{ collective_name }} has been approved as a fiscal-hosted collective under
{{ org_name }} on Open Collective.

You should have access to your collective page now. If anything looks wrong or you can't
get in, reply to this email and we'll sort it out.

Welcome aboard.

— {{ org_name }}`,
  'decision-rejected': `Subject: {{ collective_name }} — outcome of your application to {{ org_name }}

Hi,

We've reviewed the application for {{ collective_name }} and won't be taking it forward
as a fiscal-hosted collective under {{ org_name }} at this time.

This is about fit with what we host, not a judgement on the project. You're welcome to
apply again later if things change, or to look at another fiscal host that might be a
closer match.

If you'd like more detail on the decision, reply to this email.

— {{ org_name }}`
};

// Slack has no applicant-facing copy; these are reviewer-facing one-liners.
const SLACK = {
  'slack-human-needed': ':warning: *{{ collective_name }}* ({{ slug }}, applied to {{ org_name }}) needs a human decision — no activity since the last automated email. {{ collective_url }}',
  'slack-ready-for-evaluation': ':inbox_tray: *{{ collective_name }}* ({{ slug }}, applied to {{ org_name }}) submitted the application form and is ready for evaluation. {{ collective_url }}'
};

const input = $input.first().json;
const { channel, to, template } = input;
const slug = input.slug || '';
const vars = input.vars || {};

if (channel !== 'email' && channel !== 'slack') {
  throw new Error(`send-outbound: unknown channel "${channel}" — expected "email" or "slack"`);
}

// org_name and form_url are derived here, at send time, from the org code —
// they are deliberately not columns on ose_applications.
const ORG_NAMES = { OSE: 'Open Source Europe' };
const FORM_URLS = { OSE: $env.FORM_URL_OSE };
const org = (vars.org || '').toUpperCase();
const resolved = {
  ...vars,
  slug,
  org_name: ORG_NAMES[org] || vars.org,
  form_url: FORM_URLS[org]
};

const render = (tpl) => tpl.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, key) => {
  const value = resolved[key];
  if (value === undefined || value === null || value === '') {
    // Fail loudly: a half-rendered message must never reach anyone.
    throw new Error(`send-outbound: template "${template}" needs "${key}" and it was not provided`);
  }
  return String(value);
});

let subject;
let body;
if (channel === 'email') {
  const raw = EMAILS[template];
  if (!raw) throw new Error(`send-outbound: unknown email template "${template}"`);
  if (!to) throw new Error('send-outbound: channel "email" needs "to"');
  const firstBreak = raw.indexOf('\n');
  subject = render(raw.slice('Subject: '.length, firstBreak));
  body = render(raw.slice(firstBreak).trimStart());
} else {
  const raw = SLACK[template];
  if (!raw) throw new Error(`send-outbound: unknown slack template "${template}"`);
  subject = `Slack message about ${slug}`; // used only by the DRY_RUN redirect
  body = render(raw);
}

const finalTo = channel === 'slack' ? (to || $env.SLACK_CHANNEL || '') : to;
if (!finalTo) {
  throw new Error('send-outbound: no recipient — pass "to" or set SLACK_CHANNEL');
}

return [{ json: { channel, to: finalTo, slug, subject, body, suppressed: false } }];
